<?php
require_once __DIR__ . '/../includes/functions.php';
admin_required();
if(!is_admin()){http_response_code(403);exit('Administrator access required.');}
$id=max(0,(int)($_GET['id']??0));$stmt=db()->prepare("SELECT r.*,a.full_name AS created_by_name FROM rentals r LEFT JOIN admins a ON a.id=r.created_by WHERE r.id=?");$stmt->execute([$id]);$r=$stmt->fetch();if(!$r){http_response_code(404);exit('Rental not found.');}
$items=rental_items_for($id);$dates=rental_dates_for($id,true);$payments=rental_payments_for($id);$depositTransactions=rental_deposit_transactions_for($id);$charges=rental_charges_for($id);$periods=rental_billing_periods($id);$cancellation=rental_cancellation_for($id);$paid=rental_payment_total($id);$total=rental_total_amount($r);$balance=$cancellation?0:max(0,$total-$paid);$depositRequired=max(0,(float)($r['security_deposit_required']??0));$depositHeld=rental_deposit_held($id);
$ext=db()->prepare("SELECT x.*,a.full_name AS extended_by_name FROM rental_extensions x LEFT JOIN admins a ON a.id=x.extended_by WHERE x.rental_id=? ORDER BY x.extended_at,x.id");$ext->execute([$id]);$extensions=$ext->fetchAll();
