<?php if($r['schedule_type']==='flexible'):?><section class="section"><h2>Flexible Rental Dates</h2><div class="chips"><?php foreach($dates as $d):?><span class="chip"><?= date('M j, Y',strtotime($d['rental_date'])) ?><?= $d['status']!=='scheduled'?' · Released':'' ?></span><?php endforeach;?></div></section><?php endif;?>
<?php if($periods):?><section class="section"><h2>Monthly Billing Periods</h2><table><thead><tr><th>Period</th><th>Dates</th><th>Rent</th><th>Additional Charges</th><th>Status</th></tr></thead><tbody><?php foreach($periods as $bp):?><tr><td>#<?= (int)$bp['period_no'] ?></td><td><?= date('M j',strtotime($bp['period_start'])) ?> – <?= date('M j, Y',strtotime($bp['period_end'])) ?></td><td><?= money((float)$bp['rent_amount']) ?></td><td><?= money((float)$bp['charge_total']) ?></td><td><?= $bp['finalized_at']?'Finalized':'Open' ?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
