<section class="section"><h2>Payment / Refund History</h2><table><thead><tr><th>Type</th><th>Date</th><th>Method</th><th>Reference</th><th>Details</th><th>Amount</th></tr></thead><tbody><?php foreach($payments as $p): $isRefund=(string)($p['transaction_type']??'payment')==='refund'||(float)$p['amount']<0; ?><tr><td><?= $isRefund?'Refund':'Payment' ?></td><td><?= date('M j, Y g:i A',strtotime($p['paid_at'])) ?></td><td><?= e(booking_payment_method_label($p['payment_method'])) ?></td><td><?= e($p['payment_reference']?:'—') ?></td><td><?= e($p['notes']?:($isRefund?'Refund':'Payment')) ?></td><td><?= money((float)$p['amount']) ?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="6">No payments recorded.</td></tr><?php endif;?></tbody></table></section>
<?php if($depositTransactions):?><section class="section"><h2>Security Deposit History</h2><table><thead><tr><th>Date</th><th>Type</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody><?php foreach($depositTransactions as $d):?><tr><td><?= date('M j, Y g:i A',strtotime($d['transacted_at'])) ?></td><td><?= $d['transaction_type']==='refund'?'Refund':'Receipt' ?></td><td><?= e(booking_payment_method_label($d['payment_method'])) ?></td><td><?= e($d['payment_reference']?:'—') ?></td><td><?= $d['transaction_type']==='refund'?'-':'' ?><?= money((float)$d['amount']) ?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
<?php if($extensions):?><section class="section"><h2>Extension History</h2><table><thead><tr><th>Date</th><th>Change</th><th>Amount</th><th>Reason</th></tr></thead><tbody><?php foreach($extensions as $x):?><tr><td><?= date('M j, Y',strtotime($x['extended_at'])) ?></td><td><?= date('M j',strtotime($x['previous_end_date'])) ?> → <?= date('M j, Y',strtotime($x['new_end_date'])) ?><?= $x['added_dates']?'<br>'.e($x['added_dates']):'' ?></td><td><?= money((float)$x['previous_rental_amount']) ?> → <?= money((float)$x['new_rental_amount']) ?></td><td><?= e($x['reason']) ?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?>
