<?php if($r['is_complimentary']):?><section class="section box"><h2>Complimentary Rental</h2><p><?= nl2br(e($r['complimentary_reason']?:'For record purposes only.')) ?></p></section><?php endif;?>
<?php if(!empty($r['notes'])):?><section class="section box"><h2>Notes</h2><p><?= nl2br(e($r['notes'])) ?></p></section><?php endif;?>
